cat > /tmp/snap.sh <<'EOF'
source /home/judge/solution/deploy/compose/.env
curl -s -u ditto:$DITTO_PASSWORD "http://127.0.0.1:8080/api/2/search/things?option=size(200)" | python3 -c '
import json,sys
d=json.load(sys.stdin)
for t in d["items"]:
  f=t.get("features",{})
  out={}
  for k,v in f.items():
    p=v.get("properties",{})
    out[k]={kk:vv for kk,vv in p.items() if not isinstance(vv,(dict,list))}
    for kk,vv in p.items():
      if isinstance(vv,dict): out[k].update({kk+"."+a:b for a,b in vv.items() if not isinstance(b,(dict,list))})
  print(t["thingId"], json.dumps(out)[:600])
'
EOF
bash /tmp/snap.sh

