source /home/judge/solution/deploy/compose/.env
curl -s -u ditto:$DITTO_PASSWORD "http://127.0.0.1:8080/api/2/search/things?option=size(200)" | python3 -c '
import json,sys
d=json.load(sys.stdin)
g=lambda t,f,k="value": t.get("features",{}).get(f,{}).get("properties",{}).get(k)
for t in d["items"]:
  i=t["thingId"].split(":")[1]
  s=g(t,"simulation","tick")
  if i.startswith("zone"):
    si=t["features"].get("safety_interlock",{}).get("properties",{})
    print(i,"tick",s,"ch4",g(t,"methane"),g(t,"methane","quality"),"co",g(t,"co"),"af",g(t,"airflow"),"risk",g(t,"risk"),"SI",json.dumps(si)[:250])
  elif i.startswith("airway"): print(i,"tick",s,"flow",g(t,"flow"),"obs",g(t,"obstruction"),g(t,"obstruction","status"))
  elif i.startswith("fan"): print(i,"tick",s,"speed",g(t,"speed"),"req",g(t,"requested_speed"),"rpm",g(t,"rpm"),"kW",g(t,"power"),g(t,"state"))
  elif i.startswith("shearer"): print(i,"tick",s,g(t,"state"),g(t,"power"))
  else: print(i,"tick",s,"maxch4",g(t,"max_methane"),"air",g(t,"total_airflow"),"kW",g(t,"fan_power"),"paused",g(t,"simulation","paused"))
'
EOF
bash /tmp/k.sh; date; sleep 35; date; bash /tmp/k.sh

